import jax
import jax.numpy as jnp
from jax import random
import flax.linen as nn
import optax
from typing import Dict, Any

# This is the Vanilla MLP Baseline architecture from System ID 1.
class MLPNetwork(nn.Module):
    d_output: int
    hidden_dim: int = 512
    dropout_rate: float = 0.1
    task_type: str = "regression"

    @nn.compact
    def __call__(self, x, deterministic=True):
        # Flatten the sequence for MLP processing
        x = x.reshape(x.shape[0], -1) # (batch_size, seq_len * d_input)

        # Two dense layers
        x = nn.Dense(self.hidden_dim)(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        x = nn.Dense(self.hidden_dim)(x)
        x = nn.relu(x)
        x = nn.Dropout(rate=self.dropout_rate)(x, deterministic=deterministic)

        # Output layer
        x = nn.Dense(self.d_output)(x)

        # Handle output squeezing for single-output regression tasks
        if self.task_type == "regression":
            return x.squeeze(-1)
        else:
            return x

class CustomMLPNetworkWrapper:
    def __init__(self, hparams: Dict[str, Any]):
        self.network = MLPNetwork(
            d_output=hparams['d_output'],
            hidden_dim=hparams.get('hidden_dim', 512),
            dropout_rate=hparams.get('dropout_rate', 0.1),
            task_type=hparams['task_type']
        )

    def init(self, rng_key, dummy_input):
        params_key, dropout_key = random.split(rng_key)
        variables = self.network.init({'params': params_key, 'dropout': dropout_key},
                                     dummy_input, deterministic=True)
        return variables['params']

    def apply(self, params, x, deterministic=True, rng_key=None):
        if deterministic:
            return self.network.apply({'params': params}, x, deterministic=True)
        else:
            if rng_key is None:
                rng_key = random.PRNGKey(0)
            return self.network.apply({'params': params}, x, deterministic=False,
                                    rngs={'dropout': rng_key})

def _define_hyperparameters():
    return {
        'learning_rate': 0.001,
        'hidden_dim': 512,
        'dropout_rate': 0.1
    }

def create_network(hparams: Dict[str, Any]):
    return CustomMLPNetworkWrapper(hparams)

def create_optimizer(learning_rate: float = 0.001) -> optax.GradientTransformation:
    return optax.chain(
        optax.clip_by_global_norm(1.0),
        optax.adamw(learning_rate=learning_rate, weight_decay=0.01)
    )

BASE_SEED = 42
BATCH_SIZE = 64

def complete(params: Any, opt_state: Any, trial_data: Dict[str, Any]) -> None:
    ds = trial_data.get('dataset')
    vm = trial_data.get('val_metric')
    print(f"[Complete] {ds} val_metric={vm}")
